```vue src/components/kanban/KanbanContainer.vue
<script setup>
import ChatViewVue from '../../views/ChatView.vue'
import KanbanList from './KanbanList.vue'
import ChatHistoryVue from './ChatHistory.vue'
import Kanban from './Kanaban.vue'
</script>

<template>
  <div class="w-full h-full">
    <!-- Chat History -->
    <ChatHistoryVue v-if="showChatHistory" :projects="[$project, ...$projects.childProjects]" />

    <!-- Kanban list -->
    <KanbanList
      v-if="showKanbanList"
      :boards="filteredBoards"
      @select="selectBoard"
      @new="showNewBoardModal"
      @bookmark="toggleBookmark"
      @delete="onDeleteBoard"
    />

    <!-- Active chat view -->
    <ChatViewVue
      v-if="showChatView"
      class="h-full rounded-lg my-2"
      @chats="onChatEditDone"
      @sub-task="createSubTask"
      @sub-tasks="createSubTasks"
      @chat="setActiveChat($event)"
      @change-column="moveChatsToColumn"
      :kanban="activeBoard"
      :chat="$projects.activeChat"
    />

    <!-- Kanban board view -->
    <Kanban v-if="showKanban" />
  </div>
</template>

<script>
export default {
  data() {
    return {
      boardFilter: '',
      showBoardModal: false,
      showColumnModal: false,
      columnTitle: '',
      columnColor: '#000000',
      isDropdownOpen: false,
      viewColumns: [],
      topChats: [],
      loadingChats: false,
      showHistory: false
    }
  },
  computed: {
    filteredBoards() {
      return this.boardFilter ? 
        Object.values(this.rawBoards).filter(board =>
          board.title.toLowerCase().includes(this.boardFilter.toLowerCase())
        ) : this.parentBoards
    },
    showChatView() {
      return !!this.$projects.activeChat
    },
    showKanbanList() {
      return !this.$projects.activeChat && !this.showHistory
    },
    showKanban() {
      return this.board && !this.$projects.activeChat
    },
    showChatHistory() {
      return this.showHistory
    },
    board() {
      return this.$projects.activeBoard
    },
    kanban() {
      return this.$projects.kanban || { boards: {} }
    },
    rawBoards() {
      const { boards = {} } = this.kanban
      return Object.keys(boards).reduce((acc, id) => {
        acc[id] = { ...boards[id], id, title: id }
        return acc
      }, {})
    },
    activeBoard() {
      return this.rawBoards[this.$projects.activeBoard] || null
    }
  },
  methods: {
    async setActiveChat(chat) {
      if(chat) {
        await this.$projects.reloadChat(chat)
        this.$projects.setActiveChat(chat)
      }
    },
    showNewBoardModal() {
      this.showBoardModal = true
    },
    toggleBookmark({ title } = {}) {
      const boardTitle = title || this.activeBoard?.title
      const board = this.kanban.boards[boardTitle]
      if (board) {
        board.bookmark = !board.bookmark
        this.saveKanban()
      }
    },
    async selectBoard(board) {
      this.loadingChats += 1
      board = board || this.board
      try {
        this.viewColumns = []
        if (board !== this.board) {
          await this.$projects.setActiveBoard(board)
        }
        this.isDropdownOpen = false
        if (board && this.kanban.boards[board] && !this.kanban.boards[board].active) {
          Object.keys(this.kanban.boards)
            .filter(b => this.kanban.boards[b])
            .forEach(b => (this.kanban.boards[b].active = b === board))
          this.kanban.boards[board].last_update = new Date().toISOString()
          this.saveKanban()
        }
        this.showHistory = false
      } finally {
        this.loadingChats -= 1
      }
    },
    async onChatEditDone(board) {
      if (this.board !== board) this.selectBoard(board)
      await this.setActiveChat()
    },
    saveKanban() {
      this.$projects.saveKanban()
    }
  }
}
</script>
